-- MMI Minimart product catalog seed script
-- Generated from KATALOG_UTAMA_MMI.xlsx, sheet 'INVENTARIS METER'
-- Stock/inventory columns intentionally excluded.
-- Selling price = source formula: ROUNDUP((wholesale_unit*1.032483*1.07)/500,0)*500
-- See catalog_issues table for known data problems carried over from the source file.

DROP TABLE IF EXISTS products;
CREATE TABLE products (
    id INTEGER PRIMARY KEY,
    source_no INTEGER NOT NULL,
    name_latin TEXT,
    name_chinese TEXT,
    category_latin TEXT,
    category_chinese TEXT,
    size TEXT,
    unit TEXT,
    selling_price_idr INTEGER,
    image_path TEXT,
    flagged INTEGER NOT NULL DEFAULT 0,
    flag_reason TEXT
);

DROP TABLE IF EXISTS catalog_issues;
CREATE TABLE catalog_issues (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    product_id INTEGER,
    source_no INTEGER,
    sheet_row INTEGER,
    issue TEXT NOT NULL
);


